// Generated by philote from page /projects. Do not edit.
import type { Metadata } from "next";
import { connection } from "next/server";
import { Suspense } from "react";

import * as api from "@/lib/api";
import { must } from "@/lib/backend";
import { readProjectCard } from "@/lib/reads";

import ProjectCard from "@/components/common/project-card";

export const metadata: Metadata = { title: "Projects" };

export default function Page() {
    return (
        <main className="flex flex-1 flex-col">
            <Suspense fallback={<p className="px-4 py-16 text-center text-muted-foreground">Loading…</p>}>
                <Sections />
            </Suspense>
        </main>
    );
}

// Sections streams in after the page's shell.
async function Sections() {
    await connection();
    const loaded = await must(api.projects.list());
    const props1 = await Promise.all(loaded.map(readProjectCard));
    return (
        <>
            {props1.length === 0 ? (
                <p className="mx-auto w-full max-w-5xl px-4 py-16 text-center text-muted-foreground sm:px-6">{"No projects yet. Start one."}</p>
            ) : (
                <section className="mx-auto grid w-full max-w-5xl gap-6 px-4 py-8 sm:grid-cols-2 sm:px-6 lg:grid-cols-3">
                    {props1.map((item) => (
                        <ProjectCard key={item.project.id} {...item} />
                    ))}
                </section>
            )}
        </>
    );
}
